$written = 0; $skipped = 0
foreach ($item in $files) {
  $relative = $item.Path.Replace('/', [System.IO.Path]::DirectorySeparatorChar)
  $target = Join-Path $destinationRoot $relative
  if ([System.IO.File]::Exists($target)) { $skipped++; Write-Host "SKIP: $relative" -ForegroundColor Yellow; continue }
  $folder = Split-Path $target -Parent
  [System.IO.Directory]::CreateDirectory($folder) | Out-Null
  $sourceBytes = [Convert]::FromBase64String($item.Data)
  $inputStream = New-Object System.IO.MemoryStream(, $sourceBytes)
  $gzipStream = New-Object System.IO.Compression.GzipStream($inputStream, [System.IO.Compression.CompressionMode]::Decompress)
  $outputStream = New-Object System.IO.MemoryStream
  try {
    $gzipStream.CopyTo($outputStream)
    [System.IO.File]::WriteAllBytes($target, $outputStream.ToArray())
    $written++
  } finally {
    $outputStream.Dispose(); $gzipStream.Dispose(); $inputStream.Dispose()
  }
}
Write-Host "Created $written files; skipped $skipped existing files." -ForegroundColor Green
Write-Host 'Next: edit Tuan3/VeNha/index.html (personal info), add 42 real game screenshots, and commit.' -ForegroundColor Yellow
